import{_ as t,o as r,c as a,ag as o}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Week 14 — Evidence and Responsibility","description":"","frontmatter":{"source":"weeks/14-evidence-and-responsibility/README.md"},"headers":[],"relativePath":"weeks/14-evidence-and-responsibility/index.md","filePath":"weeks/14-evidence-and-responsibility/index.md"}'),s={name:"weeks/14-evidence-and-responsibility/index.md"};function n(i,e,d,l,h,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="week-14--evidence-and-responsibility" tabindex="-1">Week 14 — Evidence and Responsibility <a class="header-anchor" href="#week-14--evidence-and-responsibility" aria-label="Permalink to &quot;Week 14 — Evidence and Responsibility&quot;">​</a></h1><blockquote><p>The claims you&#39;ll hear about AI in software engineering range from &quot;10× faster&quot; to &quot;it makes everything worse&quot;; this week you argue them from the evidence, find where it runs out, and decide what you owe the maintainers, licensors and people whose data your tools touch.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>The reading and your reading response; your <strong>debate role</strong> (on Canvas) and, for speakers, three <strong>evidence cards</strong> in the debate thread by 11:59 pm the night before (<a href="./debate.html#evidence-cards">cards</a>); an <strong>oral exam 2</strong> slot booked</td></tr><tr><td><strong>Seminar</strong></td><td>Due-date quiz on the week 13 assignment · reading evidence · a <strong>structured debate</strong> on five motions (<a href="./debate.html">The Week 14 Debate</a>) · what the evidence supports · demo: counting disclosure in a fork</td></tr><tr><td><strong>Lab</strong></td><td><strong>Oral exam 2</strong> in 20-minute slots (🔴 AI off) · everyone else: the <strong>final-report sprint</strong> in teams · staff screen first upstream PRs (<a href="./lab.html">Week 14 — Lab and Assignment</a>)</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Your team&#39;s <strong>final report draft</strong> on Canvas (<a href="./lab.html#assignment--the-final-report-draft">assignment</a>) · CS [5xxx]: the study <strong>paper draft</strong> · the week 15 reading response</td></tr><tr><td><strong>AI use this week</strong></td><td>🔴 AI off: the quiz, oral exam 2, the reading response, evidence cards and the debate · 🟡 AI limited: the report draft (AI may help with tables, figures and checking claims; limitations, contributions and reflection are yours) · 🟢 AI on: fixing code the sprint turns up</td></tr><tr><td><strong>Reading</strong></td><td>The METR randomized trial with experienced open-source developers and its 2026 update, plus LLVM&#39;s AI Tool Policy (<a href="#reading">below</a>)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words, 🔴 AI off, on Canvas, before the Seminar (<a href="#reading">prompt</a>)</td></tr><tr><td><strong>Team project</strong></td><td>Final report draft; optional upstream PRs screened in the Lab (<a href="./../../project/contribution-rules.html#optional-upstream-prs-tier-3">contribution rules</a>)</td></tr><tr><td><strong>Graduate track</strong></td><td><strong>Paper draft</strong> due before the week 15 Seminar (<a href="./../../graduate/empirical-study.html#milestones">empirical study</a>); a paper presentation this week replaces the debate round on its topic</td></tr><tr><td><strong>Time</strong></td><td>Seminar and Lab 2.5 h · outside about 6 h (CS [5xxx]: about 7.5 h)</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li><strong>Grade a claim by its design:</strong> say what a randomized trial, a field experiment, a difference-in-differences study, an observational study, a survey and a policy document can and can&#39;t show, and why measured speed and perceived speed differ.</li><li><strong>State the current evidence</strong> on productivity, code quality and skills, with numbers and their uncertainty, and say where studies disagree.</li><li><strong>Compare maintainers&#39; AI policies</strong> (QEMU, Ghostty, LLVM, the Linux kernel) and apply the strictest one that binds you.</li><li><strong>Explain the licensing, attribution and privacy risks</strong> of AI-assisted work on open source, and what the course&#39;s rules do and don&#39;t cover.</li><li><strong>Show your own evidence:</strong> reproduce every number your team&#39;s final report will contain, from a fresh environment.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><p>After the <strong>due-date quiz</strong> on your week 13 assignment (7 minutes, 🔴 AI off), a short talk sets up the debate: which designs support causal claims, why self-reports overstate speed, and five questions to ask of any number (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-14.html" target="_blank" rel="noreferrer">slides</a>).</p><p>Most of the Seminar is a <strong>structured debate</strong>: five eight-minute rounds, one motion each, on productivity, quality, skills, maintainers&#39; policies, and licensing and privacy. Sides are assigned, not chosen. Every claim needs a source, and opinion is labeled as opinion. An <strong>evidence judge</strong> scores each round on the accuracy of the evidence, and the room votes before and after, so we can see whether persuasion and evidence agree. Format, roles, card template, scoring and source packs: <strong><a href="./debate.html">The Week 14 Debate</a></strong>. It counts as Seminar participation (<a href="./../../assessment/rubrics.html#seminar-participation-2-points-per-seminar">rubric</a>); the scorecards aren&#39;t grades.</p><p>The Seminar closes with what the evidence supports, and a demo: counting <code>Assisted-by:</code> trailers in a team fork against its <code>AI_LOG.md</code>.</p><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p><strong>Oral exam 2</strong> (15 minutes, individual, 🔴 AI off) runs in 20-minute slots in the Lab and in office-hour and booked slots, all inside week 14. It covers your M1 and M2 PRs, your PR-round work and your weeks 9–13 assignments (<a href="./../../assessment/oral-exams.html#oral-exam-2-week-14">Oral Exams: Oral exam 2 (week 14)</a>). There&#39;s no retake: week 15 can&#39;t hold exams.</p><p>Everyone not in a slot works with their team on a <strong>final-report sprint</strong>: reproduce every number from a fresh Codespace, fill in the status-against-spec table, and audit your claims (<a href="./lab.html">Week 14 — Lab and Assignment</a>). A <strong>screening desk</strong> checks first upstream PRs.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>Read (about 50 minutes):</strong></p><ol><li>Becker et al., <a href="https://arxiv.org/abs/2507.09089" target="_blank" rel="noreferrer">the METR randomized trial with experienced open-source developers</a> (2025): the abstract, the introduction, the main results figure, and the discussion of factors that might explain the slowdown. METR&#39;s <a href="https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/" target="_blank" rel="noreferrer">summary post</a> is a good first pass.</li><li>METR, <a href="https://metr.org/blog/2026-02-24-uplift-update/" target="_blank" rel="noreferrer">&quot;uplift update&quot;</a> (February 2026): why the follow-up&#39;s own estimates are unreliable.</li><li>LLVM, <a href="https://github.com/llvm/llvm-project/blob/main/llvm/docs/AIToolPolicy.md" target="_blank" rel="noreferrer">AI Tool Policy</a>: the source of this course&#39;s <code>Assisted-by:</code> trailer and self-written PR descriptions.</li></ol><p><strong>Reading response</strong> (150–250 words, 🔴 AI off, on Canvas, before the Seminar): State one METR result with its confidence interval. Name one selection effect the 2026 update describes, and say in which direction it pushes the estimate. Then name the rule in LLVM&#39;s policy that would be hardest for your team to follow, and say why. End with one question for the debate (<a href="./../../assessment/rubrics.html#reading-response-5-points">rubric</a>).</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>Measured is not perceived.</strong> In METR&#39;s 2025 trial, 16 experienced developers took 19% longer with AI allowed, yet believed afterwards they&#39;d been about 20% faster (<a href="https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/" target="_blank" rel="noreferrer">METR</a>).</li><li><strong>The design decides the claim.</strong> Randomized field rollouts with 4,867 developers found 26% more completed tasks, more for juniors (27–39%) than seniors (8–13%), with quality unobserved (<a href="https://pubsonline.informs.org/doi/fpi/10.1287/mnsc.2025.00535" target="_blank" rel="noreferrer">Cui et al.</a>). A difference-in-differences study of Cursor adopters found that output gains faded within about two months while warnings and complexity stayed up (<a href="https://arxiv.org/abs/2511.04427" target="_blank" rel="noreferrer">He et al.</a>). Both can be true; they measure different things.</li><li><strong>Policies converge on disclose, understand, take responsibility.</strong> Of 118 contributor AI policies, 78% allow AI-assisted contributions, 51% require disclosure and 74% require a <a href="./../../resources/glossary.html#human-in-the-loop">human in the loop</a> (<a href="https://arxiv.org/abs/2605.16706" target="_blank" rel="noreferrer">Hora &amp; Robbes</a>). They disagree on how to record it, and they change: in October 2026 the Linux kernel dropped its AI tag requirement (<a href="./../../resources/case-studies.html#e4-the-linux-kernel-drops-its-ai-tag">case E4</a>).</li><li><strong>Detection can&#39;t replace disclosure.</strong> At realistic prevalence, detectors of agent-written commits reach a precision of only 0.332 (<a href="https://arxiv.org/abs/2610.36229" target="_blank" rel="noreferrer">Horikawa et al.</a>). Your <a href="./../../resources/glossary.html#assisted-by-trailer"><code>Assisted-by:</code> trailer</a> and <code>AI_LOG.md</code> are the only reliable record.</li><li><strong>Provenance is a small, unknowable-per-output risk.</strong> Even the best of 14 models produced near-copies of existing open-source code in 0.88–2.01% of outputs and often got the license wrong (<a href="https://arxiv.org/abs/2408.02487" target="_blank" rel="noreferrer">LiCoEval</a>).</li><li><strong>What goes in matters too.</strong> Free tiers may train on your prompts (<a href="./../../TOOLS.html#the-data-rule">Tool Handout: The data rule</a>), and a prompt carries issue threads, logs and whatever the agent read.</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>Why does METR&#39;s 2026 update say its estimate probably <em>understates</em> the speedup? What would a design without that bias look like?</li><li>Cui et al. and METR 2025 disagree in sign. Give two differences in who was studied and what was measured that could explain it.</li><li>He et al.&#39;s complexity figure differs between a table and the text. How should you cite it?</li><li>Your team fork&#39;s parent project has no AI policy, but you want to send a fix upstream. Which rules apply, and whose?</li><li>Why is &quot;the code is public&quot; not a complete answer to the data rule?</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>Canvas down for the quiz or the vote:</strong> paper quiz; hands for the vote, counted by the judge.</li><li><strong>Codespaces won&#39;t start for the sprint:</strong> clone the team fork locally into a dev container (<a href="./../../setup/sandboxes.html">sandboxes</a>), or pair on a teammate&#39;s Codespace (<a href="./../../resources/troubleshooting.html#my-codespace-wont-start-or-im-out-of-hours">troubleshooting</a>).</li><li><strong>A source link breaks mid-debate:</strong> cite it from the <a href="./../../resources/reading-list.html#week-14--evidence-and-responsibility">reading list</a> or the <a href="./../../resources/case-studies.html#maintainers-ai-policies">case studies</a>, and say you couldn&#39;t open the original.</li><li><strong>Your oral exam slot falls through</strong> (examiner ill, network down): it&#39;s rescheduled inside week 14 without penalty (<a href="./../../assessment/oral-exams.html#retakes-and-make-ups">make-ups</a>).</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Borg et al., <a href="https://arxiv.org/abs/2507.00788" target="_blank" rel="noreferrer">&quot;Echoes of AI&quot;</a>: a preregistered study with no downstream maintainability effect. <strong>[Grad seminar]</strong></li><li>Lee et al., <a href="https://advait.org/files/lee_2025_ai_critical_thinking_survey.pdf" target="_blank" rel="noreferrer">&quot;The Impact of Generative AI on Critical Thinking&quot;</a>, CHI 2025. <strong>[Grad seminar]</strong></li><li>Shen &amp; Tamkin, <a href="https://arxiv.org/abs/2601.20245" target="_blank" rel="noreferrer">a randomized trial of skill formation</a>.</li><li>The <a href="./../../resources/case-studies.html#maintainers-ai-policies">maintainers&#39; AI policies</a> (cases E1–E8) and the <a href="./../../resources/reading-list.html#week-14--evidence-and-responsibility">week 14 reading list</a>.</li></ul>',26)])])}const p=t(s,[["render",n]]);export{g as __pageData,p as default};
